#!/usr/bin/env node
/**
 * Fix Strategist — Plan Renderer
 *
 * Combines:
 *   .github/.pipeline-context/fix-strategy/<id>.context.json  — facts, from collect-remediation-context.js
 *   .github/.pipeline-context/fix-strategy/<id>.strategy.json — judgement, written by the agent
 *
 * Output: docs/agent_output/04-remediation/fix_plan_<id>.md
 *
 * The rendered plan carries its approval state as a table cell (**Status**), not YAML front
 * matter — the same convention docs/agent_output/02-root-cause and docs/agent_output/03-blast-radius use for their own facts,
 * kept here for consistency. A human approves a plan by hand-editing that one cell from
 * `Proposed` to `Approved` (or `Rejected`) directly in the generated file.
 *
 * Re-rendering is safe: if a plan already exists and its Status is Approved or Rejected, that
 * status is preserved (a "re-proposed on <date>" note is appended instead) so re-running the
 * Strategist after a human decision does not silently revoke it.
 *
 * Usage:
 *   node scripts/render-fix-plan.js --all
 *   node scripts/render-fix-plan.js --issue ISSUE-001
 */
const fs = require('fs');
const path = require('path');
const {
  REPO_ROOT, OUT_DIR, OUT_README,
  rel, listRootCauseReports, loadCatalog, contextJsonPathFor, strategyPathFor, planPathFor, existingPlanStatus,
} = require('./lib/plans');

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--issue' || arg === '-i') args.issue = argv[++i];
    else if (arg === '--all' || arg === '-a') args.all = true;
    else if (arg === '--help' || arg === '-h') args.help = true;
  }
  return args;
}

function usage() {
  console.log(`Fix Strategist — Plan Renderer

  node scripts/render-fix-plan.js --all
  node scripts/render-fix-plan.js --issue <ISSUE-ID>

Options:
  --all, -a     Render every root cause report that has a strategy.json ready
  --issue, -i   A single issue id, e.g. ISSUE-001
  --help, -h    Show this message`);
}

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

const REQUIRED = [
  ['cwe', (s) => typeof s.cwe === 'string' && s.cwe.trim()],
  ['plain_summary', (s) => typeof s.plain_summary === 'string' && s.plain_summary.trim()],
  ['approach', (s) => typeof s.approach === 'string' && s.approach.trim()],
  ['catalog_reference.cwe', (s) => s.catalog_reference && s.catalog_reference.cwe],
  ['affected_files (non-empty array)', (s) => Array.isArray(s.affected_files) && s.affected_files.length > 0],
  ['verification_plan (non-empty array)', (s) => Array.isArray(s.verification_plan) && s.verification_plan.length > 0],
];

function validate(strategy) {
  const missing = REQUIRED.filter(([, check]) => !check(strategy)).map(([key]) => key);
  if (missing.length) {
    throw new Error(`Strategy JSON is missing required field(s):\n  - ${missing.join('\n  - ')}\nSee templates/strategy.schema.json for the expected shape.`);
  }
}

// ---------------------------------------------------------------------------
// Rendering helpers
// ---------------------------------------------------------------------------

function bullets(items, emptyText = '_none recorded_') {
  if (!items || !items.length) return [emptyText];
  return items.map((i) => `- ${i}`);
}

// Depth-independent: derived from where the plan is actually written.
const UP_TO_ROOT = path.relative(OUT_DIR, REPO_ROOT).replace(/\\/g, '/');

function linkFromOutput(repoRelativePath, label) {
  return `[${label || repoRelativePath}](${`${UP_TO_ROOT}/${repoRelativePath}`.replace(/\\/g, '/')})`;
}

// ---------------------------------------------------------------------------
// Report
// ---------------------------------------------------------------------------

function render(context, strategy, previousStatus, catalog) {
  const status = (previousStatus === 'Approved' || previousStatus === 'Rejected') ? previousStatus : 'Proposed';
  const catalogEntry = strategy.catalog_reference;
  const owasp = (catalog[strategy.cwe] && catalog[strategy.cwe].owasp) || null;
  const out = [];

  out.push(`# Fix Plan — ${context.id}`);
  out.push('');
  out.push(`## ${context.title}`);
  out.push('');
  out.push(`> ${strategy.plain_summary.trim()}`);
  out.push('');
  out.push(`_Generated by the Fix Strategist agent on ${new Date().toISOString().slice(0, 10)}. Context collected ${context.generatedAt}._`);
  out.push('');
  if (previousStatus === 'Approved' || previousStatus === 'Rejected') {
    out.push(`_This plan was re-proposed on ${new Date().toISOString().slice(0, 10)}; its Status (${status}) was preserved rather than reset — see the note in the Approval section._`);
    out.push('');
  }

  out.push('## At a glance');
  out.push('');
  out.push('| | |');
  out.push('|---|---|');
  out.push(`| **Status** | ${status} |`);
  out.push(`| **CWE** | \`${strategy.cwe}\`${catalogEntry.title ? ` — ${catalogEntry.title}` : ' — **catalog gap, see Open Questions**'} |`);
  out.push(`| **OWASP** | ${owasp || 'n/a'} |`);
  if (strategy.dependency_upgrade) {
    const d = strategy.dependency_upgrade;
    out.push(`| **Dependency** | \`${d.maven_coordinate}\` ${d.current_version} → ≥${d.minimum_fixed_version}${d.cve ? ` (${d.cve})` : ''} |`);
  }
  out.push(`| **Affected files** | ${strategy.affected_files.length} |`);
  out.push(`| **Confidence** | ${strategy.confidence || 'not stated'} |`);
  out.push(`| **Root cause report** | ${linkFromOutput(context.sources.rootCauseReport, context.sources.rootCauseReport)} |`);
  out.push(`| **Blast radius report** | ${context.sources.blastRadiusReport ? linkFromOutput(context.sources.blastRadiusReport, context.sources.blastRadiusReport) : 'not available'} |`);
  out.push('');

  out.push('## 1. Remediation approach');
  out.push('');
  out.push(strategy.approach.trim());
  out.push('');
  if (catalogEntry.title) {
    out.push(`**Catalog pattern (\`${catalogEntry.cwe}\`):** ${catalogEntry.title}`);
    out.push('');
  }

  if (strategy.alternatives_considered && strategy.alternatives_considered.length) {
    out.push('## 2. Alternatives considered');
    out.push('');
    bullets(strategy.alternatives_considered).forEach((b) => out.push(b));
    out.push('');
  }

  out.push(`## ${strategy.alternatives_considered && strategy.alternatives_considered.length ? '3' : '2'}. Planned changes`);
  out.push('');
  out.push('| File | Planned change |');
  out.push('|---|---|');
  for (const f of strategy.affected_files) {
    out.push(`| ${linkFromOutput(f.file, f.file.split('/').pop())} | ${(f.planned_change || '').replace(/\|/g, '\\|')} |`);
  }
  out.push('');
  if (strategy.illustrative_sketch) {
    out.push('<details><summary>Illustrative sketch (not an applied patch — the Fixer writes the actual diff)</summary>');
    out.push('');
    out.push('```java');
    out.push(strategy.illustrative_sketch.trim());
    out.push('```');
    out.push('');
    out.push('</details>');
    out.push('');
  }

  const sectionOffset = (strategy.alternatives_considered && strategy.alternatives_considered.length) ? 1 : 0;
  out.push(`## ${3 + sectionOffset}. Risks to watch`);
  out.push('');
  bullets(strategy.risk_notes, '_None recorded._').forEach((b) => out.push(b));
  out.push('');

  out.push(`## ${4 + sectionOffset}. How the fix must be verified`);
  out.push('');
  strategy.verification_plan.forEach((v, i) => out.push(`${i + 1}. ${v}`));
  out.push('');
  out.push('_The Fixer\'s verification report must address every step above, or explain why a step could not be run (e.g. it needs a live dependency unavailable in the isolated build sandbox)._');
  out.push('');

  if (strategy.open_questions && strategy.open_questions.length) {
    out.push(`## ${5 + sectionOffset}. Open questions`);
    out.push('');
    bullets(strategy.open_questions).forEach((b) => out.push(b));
    out.push('');
  }

  out.push('## Approval');
  out.push('');
  out.push('This plan is a **checkpoint**, not an authorization to write code. The Fixer agent will '
    + 'refuse to act on it while Status reads `Proposed`. To approve it, edit the **Status** cell in '
    + 'the At a glance table above from `Proposed` to `Approved` (or to `Rejected` to close it out '
    + 'without a fix) and save the file. Re-running the Fix Strategist after that will not overwrite '
    + 'your decision.');
  out.push('');

  out.push('## Appendix — inputs used');
  out.push('');
  out.push('| Input | Detail |');
  out.push('|---|---|');
  out.push(`| Root cause report | \`${context.sources.rootCauseReport}\` |`);
  out.push(`| Blast radius report | ${context.sources.blastRadiusReport ? `\`${context.sources.blastRadiusReport}\`` : 'not available'} |`);
  out.push(`| Issue report | \`${context.sources.issueFile}\` |`);
  out.push(`| CWE catalog | \`.github/skills/04a-fix-strategist/catalog/cwe-patterns.json\`, entry \`${strategy.cwe}\` |`);
  out.push('');

  out.push('---');
  out.push('');
  out.push('The affected-files list and the diagnosis quoted above are rendered from the root cause '
    + 'and issue reports. The remediation approach, alternatives, risks and verification plan are the '
    + 'judgement of the Fix Strategist agent.');
  out.push('');

  return out.join('\n');
}

// ---------------------------------------------------------------------------
// Index
// ---------------------------------------------------------------------------

const INDEX_MARKER = '<!-- AUTO-GENERATED TABLE — regenerated by 04_fix-generator (plan + fix), do not hand-edit below this line -->';

function rewriteIndex() {
  if (!fs.existsSync(OUT_DIR)) return;
  const ids = new Set();
  for (const f of fs.readdirSync(OUT_DIR)) {
    const m = /^fix_plan_(.+)\.md$/i.exec(f) || /^fix_(?!plan_)(.+)\.md$/i.exec(f);
    if (m) ids.add(m[1]);
  }
  const rows = [...ids].sort((a, b) => a.localeCompare(b, undefined, { numeric: true })).map((id) => {
    const planFile = path.join(OUT_DIR, `fix_plan_${id}.md`);
    const fixFile = path.join(OUT_DIR, `fix_${id}.md`);
    const planText = fs.existsSync(planFile) ? fs.readFileSync(planFile, 'utf8') : null;
    const fixText = fs.existsSync(fixFile) ? fs.readFileSync(fixFile, 'utf8') : null;
    const titleMatch = (planText && /^##\s+(.+)$/m.exec(planText)) || (fixText && /^##\s+(.+)$/m.exec(fixText));
    const cweMatch = planText && /\|\s*\*\*CWE\*\*\s*\|\s*`([^`]+)`/.exec(planText);
    const planStatusMatch = planText && /\|\s*\*\*Status\*\*\s*\|\s*([^|]+)\|/.exec(planText);
    const fixStatusMatch = fixText && /\|\s*\*\*Status\*\*\s*\|\s*([^|]+)\|/.exec(fixText);
    return {
      id,
      title: titleMatch ? titleMatch[1].trim() : '(untitled)',
      cwe: cweMatch ? cweMatch[1].trim() : '-',
      planStatus: planText ? (planStatusMatch ? planStatusMatch[1].trim() : 'unknown') : '_pending_',
      fixStatus: fixText ? (fixStatusMatch ? fixStatusMatch[1].trim() : 'unknown') : '_pending_',
      planFile: planText ? `fix_plan_${id}.md` : null,
      fixFile: fixText ? `fix_${id}.md` : null,
    };
  });

  const existing = fs.existsSync(OUT_README) ? fs.readFileSync(OUT_README, 'utf8') : defaultReadmeContract();
  const contract = existing.includes(INDEX_MARKER) ? existing.slice(0, existing.indexOf(INDEX_MARKER)) : existing.trimEnd() + '\n\n';

  const table = [INDEX_MARKER, ''];
  if (!rows.length) {
    table.push('_No fix plans or fixes yet — run the Fix Generator agent against a root cause report._', '');
  } else {
    table.push('| ID | Title | CWE | Plan Status | Fix Status | Plan | Fix |', '|---|---|---|---|---|---|---|');
    for (const r of rows) {
      const planLink = r.planFile ? `[${r.planFile}](./${r.planFile})` : '_none_';
      const fixLink = r.fixFile ? `[${r.fixFile}](./${r.fixFile})` : '_none_';
      table.push(`| ${r.id} | ${r.title} | \`${r.cwe}\` | ${r.planStatus} | ${r.fixStatus} | ${planLink} | ${fixLink} |`);
    }
    table.push('');
  }

  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(OUT_README, contract.trimEnd() + '\n\n' + table.join('\n'));
}

function defaultReadmeContract() {
  return `# Remediation

Fix plans and compiled patches produced by the **Fix Generator** agent (\`04_fix-generator\`), one
pair per diagnosed defect in [\`docs/agent_output/02-root-cause/\`](../02-root-cause/):

- **\`fix_plan_<id>.md\`** — Stage 1's remediation strategy, citing a CWE-aligned pattern from
  [\`.github/skills/04a-fix-strategist/catalog/cwe-patterns.json\`](../../.github/skills/04a-fix-strategist/catalog/cwe-patterns.json).
  Never contains a diff. Starts at **Status: Proposed**.
- **\`fix_<id>.md\` + \`fix_<id>.diff\`** — Stage 2's compiled patch, drafted only once a human edits
  the plan's Status to **Approved**. The diff is a standalone, directly \`git apply\`-able patch —
  Stage 2 never edits the real working tree itself. Written by \`04b-fixer\` for a code-logic fix, or
  by \`04c-dependency-upgrader\` for a \`CWE-1104\` dependency-version fix — same output location and
  Status vocabulary either way.

## The approval checkpoint

Every plan starts with **Status: Proposed**. Stage 2 will not act on a plan until a human edits that
Status cell in the plan's own file to **Approved** (or to **Rejected** to close it out). This is a
deliberate pause point between choosing a remediation strategy and writing code.

## A Compiled patch is not a merge signal

It only means the module builds (and, for a dependency upgrade, that the resolved version also meets
the target). Whether the patch actually closes the vulnerability, survives adversarial re-testing,
passes a real test/build gate, and is safe to ship is decided by the rest of the pipeline — see
[\`docs/agent_output/07-ship/\`](../07-ship/) for the final verdict.

## Reading Fix Status

- **Compiled** — the patch applied cleanly and the affected module compiled (and, if a target test
  was named, passed it) inside an isolated \`git worktree\`. For a dependency upgrade, this also means
  the resolved \`dependency:tree\` version met the plan's target.
- **Compile Failed** — the patch was drafted but did not apply cleanly, or the build/version check
  failed. The report and diff are still published for review; do not apply a patch marked this way.
- **Refused** — Stage 2 would not act because the plan was not \`Status: Approved\` at the time (or,
  for \`04c-dependency-upgrader\`, because the plan's CWE was not \`CWE-1104\`).

## Pipeline state

Run \`node .github/skills/04a-fix-strategist/scripts/list-remediation-workload.js\`,
\`node .github/skills/04b-fixer/scripts/list-fix-workload.js\`, or
\`node .github/skills/04c-dependency-upgrader/scripts/list-fix-workload.js\` for the live pipeline
state — this table is for humans; the pipeline itself discovers plans and fixes by scanning
\`docs/agent_output/04-remediation/fix_plan_*.md\` and \`fix_*.md\`.

`;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

function renderOne(id, catalog) {
  const contextFile = contextJsonPathFor(id);
  if (!fs.existsSync(contextFile)) {
    throw new Error(`No context bundle at ${rel(contextFile)}. Run collect-remediation-context.js --issue ${id} first.`);
  }
  const context = JSON.parse(fs.readFileSync(contextFile, 'utf8'));

  const strategyFile = strategyPathFor(id);
  if (!fs.existsSync(strategyFile)) {
    throw new Error(`No strategy file at ${rel(strategyFile)}.\nRead ${rel(contextFile).replace('.context.json', '.context.md')} and write your strategy there following templates/strategy.schema.json, then re-run.`);
  }
  let strategy;
  try {
    strategy = JSON.parse(fs.readFileSync(strategyFile, 'utf8'));
  } catch (err) {
    throw new Error(`Strategy file ${rel(strategyFile)} is not valid JSON: ${err.message}`);
  }
  validate(strategy);

  if (strategy.issue_id && strategy.issue_id !== context.id) {
    throw new Error(`Strategy is for ${strategy.issue_id} but the context bundle is for ${context.id}.`);
  }

  const previousStatus = existingPlanStatus(context.id);
  const target = planPathFor(context.id);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, render(context, strategy, previousStatus, catalog));

  return {
    id: context.id,
    cwe: strategy.cwe,
    status: (previousStatus === 'Approved' || previousStatus === 'Rejected') ? previousStatus : 'Proposed',
    plan: rel(target),
  };
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) return usage();

  const catalog = loadCatalog();

  if (args.all) {
    const targets = listRootCauseReports();
    if (!targets.length) throw new Error('No root cause reports found. Nothing to render.');

    const written = [];
    const skipped = [];
    for (const t of targets) {
      try {
        const result = renderOne(t.id, catalog);
        written.push(result);
        console.log(`${result.id.padEnd(10)} ${result.cwe.padEnd(10)} status ${result.status.padEnd(10)} -> ${result.plan}`);
      } catch (err) {
        skipped.push({ id: t.id, reason: err.message.split('\n')[0] });
        console.error(`${t.id.padEnd(10)} SKIPPED  ${err.message.split('\n')[0]}`);
      }
    }

    rewriteIndex();
    console.log(`\nWrote ${written.length}/${targets.length} plan(s) to ${rel(OUT_DIR)}.`);
    if (skipped.length) {
      console.log(`Still pending: ${skipped.map((s) => s.id).join(', ')} — collect context and write the strategy JSON for each, then re-run.`);
      process.exitCode = 1;
    }
    return;
  }

  if (!args.issue) {
    throw new Error('Missing --issue. Pass an issue id (--issue ISSUE-001) or --all to render every root cause report.');
  }
  const result = renderOne(args.issue, catalog);
  rewriteIndex();
  console.log(`Fix Strategist — wrote ${result.plan}`);
  console.log(`  issue  : ${result.id}`);
  console.log(`  cwe    : ${result.cwe}`);
  console.log(`  status : ${result.status}`);
}

try {
  main();
} catch (err) {
  console.error('Rendering failed:', err.message);
  process.exit(1);
}
